#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_find_max_precedence_type() {
        let v = vec![
            DType::Bool,
            DType::Int32,
            DType::Float32,
            DType::UInt64,
            DType::Int8,
        ];
        // UInt64 has precedence 8, Float32 has 9 → Float32 is max
        assert_eq!(find_max_precedence_type(v), DType::Float32);

        let v2 = vec![DType::Int16, DType::Int8, DType::Int32];
        assert_eq!(find_max_precedence_type(v2), DType::Int32);
    }

    #[test]
    fn test_find_common_type_only_arrays() {
        let arr = vec![DType::Int8, DType::Int64];
        let scal = Vec::new();
        // array-only case → max-over-arrays
        assert_eq!(find_common_type(arr, scal), Some(DType::Int64));
    }

    #[test]
    fn test_find_common_type_only_scalars() {
        let arr = Vec::new();
        let scal = vec![DType::Bool, DType::Float64];
        assert_eq!(find_common_type(arr, scal), Some(DType::Float64));
    }

    #[test]
    fn test_find_common_type_both_same_kind() {
        // both maxima are floats → return array max
        let arr = vec![DType::Float32, DType::Float64];
        let scal = vec![DType::Float32];
        assert_eq!(find_common_type(arr, scal), Some(DType::Float64));
    }

    #[test]
    fn test_find_common_type_both_diff_kind() {
        // array max is int, scalar max is float → return scalar max
        let arr = vec![DType::Int32, DType::Int16];
        let scal = vec![DType::Float32];
        assert_eq!(find_common_type(arr, scal), Some(DType::Float32));
    }

    #[test]
    fn test_find_common_type_both_empty() {
        assert_eq!(find_common_type(Vec::new(), Vec::new()), None);
    }
}